// ==UserScript==
// @name         АнтиАристарх
// @namespace    anti-aristarh
// @version      0.5.0
// @homepageURL   https://github.com/TTTenet/AntiAristarh
// @updateURL     https://raw.githubusercontent.com/TTTenet/AntiAristarh/main/AntiAristarh.user.js
// @downloadURL   https://raw.githubusercontent.com/TTTenet/AntiAristarh/main/AntiAristarh.user.js
// @description  Находит специальные и другие скрытые фрагменты страницы.
// @author       TTTenet
// @match        *://*/*
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// ==/UserScript==

(() => {
    'use strict';

    const ROOT_ID = 'anti-aristarh-root';
    const VERSION = '0.5.0';
    const AVATAR = 'data:image/png;base64,';
    const IS_ARYAPAW = location.hostname === 'aryapaw.dev' || location.hostname.endsWith('.aryapaw.dev');

    if (document.getElementById(ROOT_ID)) return;

    // Настройки хранятся отдельно для каждого домена в хранилище Tampermonkey.
    const SETTINGS_KEY = `anti-aristarh-settings:${location.hostname.toLowerCase()}`;
    let savedSettings = {};
    try {
        savedSettings = GM_getValue(SETTINGS_KEY, {}) || {};
    } catch (_) {
        savedSettings = {};
    }

    const state = {
        markerReveal: Boolean(savedSettings.markerReveal),
        reveal: Boolean(savedSettings.reveal),
        blockCopy: Boolean(savedSettings.blockCopy)
    };
    let isMinimized = typeof savedSettings.minimized === 'boolean'
        ? savedSettings.minimized
        : !IS_ARYAPAW;

    function saveSettings() {
        try {
            GM_setValue(SETTINGS_KEY, {
                markerReveal: state.markerReveal,
                reveal: state.reveal,
                blockCopy: state.blockCopy,
                minimized: isMinimized
            });
        } catch (error) {
            console.warn('[АнтиАристарх] Не удалось сохранить настройки:', error);
        }
    }

    // Элементы и текстовые узлы, в которых обнаружен скрытый текст.
    const hiddenTextElements = new Set();
    const hiddenTextNodes = new Set();
    const assignmentMarkerTextNodes = new Set();
    const assignmentMarkerElements = new Set();
    // Элементы, которые пришлось раскрыть (например, display:none).
    const revealedRoots = new Set();

    // Храним исходные inline-стили, чтобы точно вернуть их при выключении режима.
    // У одного свойства могут быть несколько владельцев: reveal и block.
    const styleRecords = new Map();
    const hiddenAttributeRecords = new Map();
    const revealedRootReasons = new Map();

    const panel = document.createElement('div');
    panel.id = ROOT_ID;
    panel.style.cssText = [
        'position:fixed',
        'right:18px',
        'bottom:18px',
        'z-index:2147483647',
        'width:310px',
        'max-width:calc(100vw - 36px)',
        'font:14px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif',
        'color:#f4f1fa',
        'isolation:isolate'
    ].join(';');

    const shadow = panel.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
        <style>
            :host { all: initial; }
            * { box-sizing: border-box; }
            .panel {
                position:relative;
                overflow:visible;
                border:1px solid rgba(255,255,255,.13);
                border-radius:15px;
                background:#17151d;
                color:#f4f1fa;
                box-shadow:0 12px 36px rgba(0,0,0,.38);
                font:13px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
            }
            .top {
                display:flex; align-items:center; justify-content:space-between;
                padding:12px 14px 10px; border-bottom:1px solid rgba(255,255,255,.09);
            }
            .brand { display:flex; align-items:center; gap:9px; font-weight:700; letter-spacing:.1px; white-space:nowrap; }
            .top-actions { display:flex; align-items:center; gap:7px; }
            .mark {
                display:block; width:27px; height:27px; flex:0 0 27px;
                border-radius:8px; object-fit:cover; background:#29242f;
                box-shadow:0 0 16px rgba(255,38,61,.18);
            }
            .version { color:#827d8c; font-size:10px; font-weight:500; white-space:nowrap; }
            .icon-button {
                display:grid; place-items:center; width:25px; height:25px; padding:0;
                border:0; border-radius:6px; background:transparent; color:#aaa4b4;
                cursor:pointer; font:16px/1 Arial,sans-serif;
            }
            .icon-button:hover { background:rgba(255,255,255,.09); color:#fff; }
            .minimize { font-size:20px; }
            .info-card {
                display:none; position:absolute; top:47px; right:10px; z-index:10;
                width:min(276px, calc(100vw - 56px)); padding:13px;
                border:1px solid rgba(255,255,255,.14); border-radius:11px;
                background:#24212b; color:#eeeaf5; box-shadow:0 10px 28px rgba(0,0,0,.42);
            }
            .info-card.open { display:block; }
            .info-title { margin:0 0 7px; font-size:12px; font-weight:700; }
            .info-text { margin:0; color:#c5bfce; font-size:11px; line-height:1.55; }
            .rows { padding:5px 8px; }
            .toggle {
                width:100%; display:flex; align-items:center; justify-content:space-between;
                gap:12px; padding:10px 7px; border:0; border-radius:9px;
                background:transparent; color:inherit; text-align:left; cursor:pointer;
                font:inherit;
            }
            .toggle + .toggle { border-top:1px solid rgba(255,255,255,.07); }
            .toggle:hover { background:rgba(255,255,255,.055); }
            .toggle:focus-visible, .icon-button:focus-visible, .restore:focus-visible {
                outline:2px solid #ff4054; outline-offset:2px;
            }
            .label { display:block; color:#f5f2f8; font-weight:600; font-size:12px; }
            .hint { display:block; max-width:235px; color:#918b9c; font-size:10px; line-height:1.35; margin-top:2px; }
            .switch {
                position:relative; flex:0 0 auto; width:36px; height:21px;
                border-radius:20px; background:#46414d; transition:background .18s ease;
            }
            .switch::after {
                content:""; position:absolute; width:15px; height:15px; left:3px; top:3px;
                border-radius:50%; background:#fff; transition:transform .18s ease;
                box-shadow:0 1px 3px rgba(0,0,0,.3);
            }
            .toggle[aria-pressed="true"] .switch { background:#ff263d; }
            .toggle[aria-pressed="true"] .switch::after { transform:translateX(15px); }
            .footer {
                display:flex; align-items:center; justify-content:space-between; gap:8px;
                padding:9px 14px 10px; border-radius:0 0 15px 15px;
                background:rgba(255,255,255,.025); color:#8e8998; font-size:10px;
            }
            .footer-status { flex:1; min-width:0; line-height:1.35; align-self:center; }
            .counts { display:flex; flex-direction:column; align-items:flex-end; justify-content:center; gap:3px; white-space:nowrap; }
            .count-row {
                display:flex; align-items:center; gap:4px; padding:0; margin:0;
                border:0; background:transparent; color:#b8b1c1; cursor:pointer;
                font:inherit; font-size:9px; line-height:1.35;
            }
            .count-row:hover { color:#fff; text-decoration:underline; text-decoration-color:rgba(255,82,100,.65); }
            .count-row:focus-visible { outline:2px solid #ff4054; outline-offset:3px; border-radius:3px; }
            .count { color:#ff5264; font-weight:500; font-size:10px; }
            .results-card {
                display:none; position:absolute; right:0; bottom:calc(100% + 9px); z-index:20;
                width:100%; max-height:min(340px, calc(100vh - 105px)); min-height:130px;
                flex-direction:column; overflow:hidden; border:1px solid rgba(255,255,255,.14);
                border-radius:12px; background:#201d27; color:#f4f1fa;
                box-shadow:0 12px 34px rgba(0,0,0,.48);
            }
            .results-card.open { display:flex; }
            .results-head { display:flex; align-items:center; justify-content:space-between; gap:10px; padding:10px 11px; border-bottom:1px solid rgba(255,255,255,.09); }
            .results-title { color:#f5f2f8; font-size:11px; font-weight:700; }
            .results-summary { margin-top:2px; color:#918b9c; font-size:9px; }
            .results-close { flex:0 0 24px; }
            .results-list { overflow:auto; overscroll-behavior:contain; padding:5px; }
            .result-item { display:block; width:100%; padding:8px; border:0; border-radius:7px; background:transparent; color:inherit; text-align:left; cursor:pointer; font:inherit; }
            .result-item:hover { background:rgba(255,255,255,.07); }
            .result-item + .result-item { border-top:1px solid rgba(255,255,255,.05); }
            .result-meta { display:block; margin-bottom:3px; color:#ff7180; font-size:9px; font-weight:650; overflow-wrap:anywhere; }
            .result-text { display:block; color:#e8e3ed; font-size:10px; line-height:1.4; overflow-wrap:anywhere; white-space:pre-wrap; }
            .results-empty { padding:17px 10px; color:#918b9c; font-size:10px; text-align:center; }
            .avatar-button {
                display:inline-flex; align-items:center; justify-content:center;
                border:0; padding:0; margin:0; border-radius:9px; background:transparent;
                cursor:default; font:inherit;
            }
            .avatar-button.avatar-clickable { cursor:pointer; }
            .avatar-button:focus-visible { outline:2px solid #ff4054; outline-offset:3px; }
            .restore {
                display:none; width:auto; max-width:calc(100vw - 36px); align-items:center;
                justify-content:center; padding:9px 12px; border:1px solid rgba(255,255,255,.13);
                border-radius:12px; background:#17151d; color:#f4f1fa;
                box-shadow:0 8px 25px rgba(0,0,0,.35);
                font:13px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; cursor:pointer;
            }
            .restore:hover { background:#24212b; }
            .restore-brand { display:flex; align-items:center; gap:8px; white-space:nowrap; font-weight:650; }
            .restore .restore-mark { display:block; width:25px; height:25px; flex:0 0 25px; border-radius:7px; object-fit:cover; }
            .restore-arrow { display:none; width:16px; height:16px; align-items:center; justify-content:center; font-size:14px; line-height:1; font-weight:600; }
            .restore.minimal-launcher { width:27px; height:27px; min-width:27px; padding:0; border-radius:50%; }
            .restore.minimal-launcher .restore-brand { display:none; }
            .restore.minimal-launcher .restore-arrow { display:flex; }
            @media (prefers-reduced-motion: reduce) { .switch, .switch::after { transition:none; } }
        </style>
        <button class="restore" id="restore-panel" type="button" aria-label="Открыть АнтиАристарх" title="Открыть АнтиАристарх">
            <span class="restore-brand"><img class="restore-mark" src="${AVATAR}" alt=""><span>АнтиАристарх</span></span>
            <span class="restore-arrow" aria-hidden="true">↑</span>
        </button>
        <section class="panel" id="main-panel" aria-label="АнтиАристарх">
            <header class="top">
                <div class="brand"><button class="avatar-button" id="avatar-trigger" type="button" aria-label="Аватар АнтиАристарх" title="Аватар АнтиАристарх"><img class="mark" src="${AVATAR}" alt=""></button><span>АнтиАристарх</span></div>
                <div class="top-actions">
                    <span class="version">v${VERSION}</span>
                    <button class="icon-button" id="info-toggle" type="button" aria-label="Информация" aria-expanded="false" title="Информация">ⓘ</button>
                    <button class="icon-button minimize" id="minimize-panel" type="button" aria-label="Свернуть окно" title="Свернуть">−</button>
                </div>
            </header>
            <aside class="info-card" id="info-card" aria-label="Информация об АнтиАристарх">
                <div class="info-title">Об АнтиАристархе</div>
                <p class="info-text">Все подлянки от Аристарха показываются и не копируются — вы можете спокойно пользоваться ИИ. Показывает скрытый текст на странице и блокирует его обычное копирование.</p>
            </aside>
            <div class="rows">
                <button class="toggle" id="marker-toggle" type="button" aria-pressed="false">
                    <span>
                        <span class="label" id="marker-label">Показать текст</span>
                        <span class="hint">Показывает только текст, специально скрытый для проверки на ИИ.</span>
                    </span>
                    <span class="switch" aria-hidden="true"></span>
                </button>
                <button class="toggle" id="reveal-toggle" type="button" aria-pressed="false">
                    <span>
                        <span class="label" id="reveal-label">Показать ВЕСЬ текст</span>
                        <span class="hint">Показывает весь скрытый текст и блоки — системные и обычные.</span>
                    </span>
                    <span class="switch" aria-hidden="true"></span>
                </button>
                <button class="toggle" id="copy-toggle" type="button" aria-pressed="false">
                    <span>
                        <span class="label" id="copy-label">Заблокировать копирование</span>
                        <span class="hint">Скрытый текст можно выделить, но он не попадёт в буфер обмена.</span>
                    </span>
                    <span class="switch" aria-hidden="true"></span>
                </button>
            </div>
            <footer class="footer">
                <span class="footer-status" id="status">Сканирование страницы</span>
                <span class="counts">
                    <button class="count-row" id="total-count-trigger" type="button" aria-label="Показать все обнаруженные скрытые HTML-элементы" title="Открыть список всех скрытых элементов">Всего найдено: <b class="count" id="total-count">0</b></button>
                    <button class="count-row" id="marker-count-trigger" type="button" aria-label="Показать элементы data-assignment-marker" title="Открыть список элементов data-assignment-marker">Найдено: <b class="count" id="marker-count">0</b></button>
                </span>
            </footer>
            <aside class="results-card" id="results-card" aria-label="Список найденных элементов">
                <div class="results-head">
                    <div>
                        <div class="results-title" id="results-title">Найденные элементы</div>
                        <div class="results-summary" id="results-summary">0 элементов</div>
                    </div>
                    <button class="icon-button results-close" id="results-close" type="button" aria-label="Закрыть список" title="Закрыть">×</button>
                </div>
                <div class="results-list" id="results-list"></div>
            </aside>
        </section>
    `;

    (document.body || document.documentElement).appendChild(panel);

    const mainPanel = shadow.getElementById('main-panel');
    const minimizeButton = shadow.getElementById('minimize-panel');
    const restoreButton = shadow.getElementById('restore-panel');
    const avatarButton = shadow.getElementById('avatar-trigger');
    const infoButton = shadow.getElementById('info-toggle');
    const infoCard = shadow.getElementById('info-card');
    const markerButton = shadow.getElementById('marker-toggle');
    const revealButton = shadow.getElementById('reveal-toggle');
    const copyButton = shadow.getElementById('copy-toggle');
    const markerLabel = shadow.getElementById('marker-label');
    const revealLabel = shadow.getElementById('reveal-label');
    const copyLabel = shadow.getElementById('copy-label');
    const statusLabel = shadow.getElementById('status');
    const totalCountLabel = shadow.getElementById('total-count');
    const markerCountLabel = shadow.getElementById('marker-count');
    const totalCountTrigger = shadow.getElementById('total-count-trigger');
    const markerCountTrigger = shadow.getElementById('marker-count-trigger');
    const resultsCard = shadow.getElementById('results-card');
    const resultsTitle = shadow.getElementById('results-title');
    const resultsSummary = shadow.getElementById('results-summary');
    const resultsList = shadow.getElementById('results-list');
    const resultsClose = shadow.getElementById('results-close');
    let activeResultsType = null;

    function setMinimized(minimized, persist = true) {
        isMinimized = Boolean(minimized);
        mainPanel.style.display = isMinimized ? 'none' : '';
        restoreButton.style.display = isMinimized ? 'flex' : 'none';
        panel.style.width = isMinimized ? 'fit-content' : '310px';
        if (isMinimized) {
            infoCard.classList.remove('open');
            resultsCard.classList.remove('open');
            activeResultsType = null;
            infoButton.setAttribute('aria-expanded', 'false');
        } else if (!IS_ARYAPAW) {
            // На сторонних сайтах сканируем страницу только после открытия панели.
            scanPage();
        }
        if (persist) saveSettings();
    }

    minimizeButton.addEventListener('click', () => setMinimized(true));
    restoreButton.addEventListener('click', () => setMinimized(false));

    let siteHackActive = false;
    if (IS_ARYAPAW) {
        avatarButton.classList.add('avatar-clickable');
        avatarButton.title = 'Переключить визуальный режим сайта';
        avatarButton.setAttribute('aria-label', 'Переключить визуальный режим сайта');
        avatarButton.addEventListener('click', () => {
            const commandName = siteHackActive ? 'unhack' : 'hack';
            const commandText = `${commandName} ()`;
            console.log(commandText);

            // The page's own command is called when it is exposed in the page context.
            // No hack/unhack effect is implemented by АнтиАристарх itself.
            try {
                const pageFunction = window[commandName];
                if (typeof pageFunction === 'function') {
                    pageFunction.call(window);
                } else if (typeof window.eval === 'function') {
                    // Some sites expose console commands as global lexical bindings, not window properties.
                    const isAvailable = window.eval(`typeof ${commandName} === 'function'`);
                    if (isAvailable) window.eval(commandText);
                }
            } catch (_) {
                // The command text is still written to the console; no site code is added here.
            }
            siteHackActive = !siteHackActive;
        });
    }

    if (!IS_ARYAPAW) {
        restoreButton.classList.add('minimal-launcher');
    }
    // Восстанавливаем сохранённое состояние окна без повторной записи настроек.
    setMinimized(isMinimized, false);

    infoButton.addEventListener('click', () => {
        const isOpen = infoCard.classList.toggle('open');
        infoButton.setAttribute('aria-expanded', String(isOpen));
    });

    function saveAndSetStyle(element, property, value, owner) {
        if (!element || !element.style) return;

        let properties = styleRecords.get(element);
        if (!properties) {
            properties = new Map();
            styleRecords.set(element, properties);
        }

        let record = properties.get(property);
        if (!record) {
            record = {
                value: element.style.getPropertyValue(property),
                priority: element.style.getPropertyPriority(property),
                owners: new Set()
            };
            properties.set(property, record);
        }

        record.owners.add(owner);
        element.style.setProperty(property, value, 'important');
    }

    function restoreStyleOwner(owner) {
        for (const [element, properties] of styleRecords) {
            for (const [property, record] of properties) {
                record.owners.delete(owner);
                if (record.owners.size === 0) {
                    if (record.value) {
                        element.style.setProperty(property, record.value, record.priority);
                    } else {
                        element.style.removeProperty(property);
                    }
                    properties.delete(property);
                }
            }
            if (properties.size === 0) styleRecords.delete(element);
        }
    }

    function removeHiddenAttribute(element) {
        if (!element.hasAttribute('hidden')) return;
        if (!hiddenAttributeRecords.has(element)) {
            hiddenAttributeRecords.set(element, element.getAttribute('hidden'));
        }
        element.removeAttribute('hidden');
    }

    function restoreHiddenAttributes() {
        for (const [element, value] of hiddenAttributeRecords) {
            element.setAttribute('hidden', value === null ? '' : value);
        }
        hiddenAttributeRecords.clear();
    }

    function defaultDisplay(element) {
        const tag = element.tagName.toLowerCase();
        const displayMap = {
            span: 'inline', a: 'inline', b: 'inline', strong: 'inline', em: 'inline',
            i: 'inline', u: 'inline', s: 'inline', small: 'inline', big: 'inline',
            code: 'inline', abbr: 'inline', label: 'inline', q: 'inline', mark: 'inline',
            sub: 'inline', sup: 'inline', time: 'inline', cite: 'inline', dfn: 'inline',
            img: 'inline-block', button: 'inline-block', input: 'inline-block',
            li: 'list-item', table: 'table', thead: 'table-header-group',
            tbody: 'table-row-group', tfoot: 'table-footer-group', tr: 'table-row',
            td: 'table-cell', th: 'table-cell', caption: 'table-caption',
            colgroup: 'table-column-group', col: 'table-column'
        };
        return displayMap[tag] || 'block';
    }

    function colorIsTransparent(color) {
        if (!color) return false;
        if (String(color).trim().toLowerCase() === 'transparent') return true;
        const match = color.match(/rgba?\(([^)]+)\)/i);
        if (!match) return false;
        const parts = match[1].split(',').map(part => part.trim());
        return parts.length >= 4 && Number.parseFloat(parts[3]) <= 0.01;
    }

    function isFarOffscreen(element, style) {
        if (style.position !== 'absolute' && style.position !== 'fixed') return false;
        const rect = element.getBoundingClientRect();
        return rect.right < -1000 || rect.left > window.innerWidth + 1000;
    }

    function findHiddenCauses(textElement) {
        const causes = [];
        const seen = new Set();
        const effectiveVisibility = window.getComputedStyle(textElement).visibility;

        function addCause(root, type) {
            const key = `${type}:${causes.length}`;
            if (!seen.has(key)) {
                seen.add(key);
                causes.push({ root, type });
            }
        }

        for (let current = textElement; current && current.nodeType === 1; current = current.parentElement) {
            if (current === panel || current.id === ROOT_ID) break;

            let style;
            try {
                style = window.getComputedStyle(current);
            } catch (_) {
                continue;
            }

            if (current.hidden || style.display === 'none') addCause(current, 'display');
            if ((style.visibility === 'hidden' || style.visibility === 'collapse') &&
                (effectiveVisibility === 'hidden' || effectiveVisibility === 'collapse')) {
                addCause(current, 'visibility');
            }
            if (Number.parseFloat(style.opacity) <= 0.02) addCause(current, 'opacity');
            if (style.contentVisibility === 'hidden') addCause(current, 'content-visibility');
            if (style.clipPath && style.clipPath !== 'none' && /inset\(\s*50%|circle\(\s*0/i.test(style.clipPath)) {
                addCause(current, 'clip-path');
            }
            if (style.clip && style.clip !== 'auto' && /rect\(\s*0(px)?\s*,\s*0(px)?\s*,\s*0(px)?\s*,\s*0(px)?\s*\)/i.test(style.clip)) {
                addCause(current, 'clip');
            }
            if (isFarOffscreen(current, style)) addCause(current, 'offscreen');

            if (current === textElement) {
                if (colorIsTransparent(style.color) || colorIsTransparent(style.webkitTextFillColor)) {
                    addCause(current, 'color');
                }
                if (Number.parseFloat(style.fontSize) <= 0.5) addCause(current, 'font-size');
                if (Number.parseFloat(style.textIndent) <= -1000) addCause(current, 'text-indent');

                if (style.overflow !== 'visible') {
                    const rect = current.getBoundingClientRect();
                    if (rect.width <= 1 && rect.height <= 1) addCause(current, 'zero-size');
                }
            }
        }
        return causes;
    }

    function findRevealedAncestor(element) {
        for (let current = element; current && current.nodeType === 1; current = current.parentElement) {
            if (revealedRoots.has(current)) return current;
        }
        return null;
    }

    function revealRoot(cause) {
        const element = cause.root;
        if (!element) return;

        let appliedReasons = revealedRootReasons.get(element);
        if (!appliedReasons) {
            appliedReasons = new Set();
            revealedRootReasons.set(element, appliedReasons);
        }
        if (appliedReasons.has(cause.type)) return;
        appliedReasons.add(cause.type);
        revealedRoots.add(element);
        removeHiddenAttribute(element);

        switch (cause.type) {
            case 'display':
                saveAndSetStyle(element, 'display', defaultDisplay(element), 'reveal');
                break;
            case 'visibility':
                saveAndSetStyle(element, 'visibility', 'visible', 'reveal');
                break;
            case 'opacity':
                saveAndSetStyle(element, 'opacity', '1', 'reveal');
                break;
            case 'content-visibility':
                saveAndSetStyle(element, 'content-visibility', 'visible', 'reveal');
                break;
            case 'clip-path':
                saveAndSetStyle(element, 'clip-path', 'none', 'reveal');
                break;
            case 'clip':
                saveAndSetStyle(element, 'clip', 'auto', 'reveal');
                break;
            case 'color':
                saveAndSetStyle(element, 'color', '#ff102a', 'reveal');
                saveAndSetStyle(element, '-webkit-text-fill-color', '#ff102a', 'reveal');
                break;
            case 'font-size': {
                const parentSize = element.parentElement
                    ? window.getComputedStyle(element.parentElement).fontSize
                    : '16px';
                saveAndSetStyle(element, 'font-size', parentSize === '0px' ? '16px' : parentSize, 'reveal');
                break;
            }
            case 'text-indent':
                saveAndSetStyle(element, 'text-indent', '0', 'reveal');
                break;
            case 'offscreen':
                saveAndSetStyle(element, 'position', 'static', 'reveal');
                saveAndSetStyle(element, 'left', 'auto', 'reveal');
                saveAndSetStyle(element, 'right', 'auto', 'reveal');
                saveAndSetStyle(element, 'transform', 'none', 'reveal');
                break;
            case 'zero-size':
                saveAndSetStyle(element, 'width', 'auto', 'reveal');
                saveAndSetStyle(element, 'height', 'auto', 'reveal');
                saveAndSetStyle(element, 'overflow', 'visible', 'reveal');
                break;
        }
    }

    function highlightText(element) {
        saveAndSetStyle(element, 'color', '#ff102a', 'reveal');
        saveAndSetStyle(element, '-webkit-text-fill-color', '#ff102a', 'reveal');
        saveAndSetStyle(element, 'background-color', 'rgba(255, 16, 42, 0.10)', 'reveal');
        saveAndSetStyle(element, 'text-shadow', '0 0 0 #ff102a', 'reveal');
    }

    // Отдельный режим для специальных меток Аристарха: показываем только
    // содержимое элементов [data-assignment-marker], не раскрывая остальные блоки.
    function revealAssignmentMarker(element, owner) {
        if (!element || element.nodeType !== 1) return;

        const computed = window.getComputedStyle(element);
        const parentFontSize = element.parentElement
            ? window.getComputedStyle(element.parentElement).fontSize
            : '16px';
        const fontSize = parentFontSize && parentFontSize !== '0px' ? parentFontSize : '16px';

        if (computed.display === 'none') saveAndSetStyle(element, 'display', 'inline', owner);
        saveAndSetStyle(element, 'visibility', 'visible', owner);
        saveAndSetStyle(element, 'opacity', '1', owner);
        saveAndSetStyle(element, 'content-visibility', 'visible', owner);
        saveAndSetStyle(element, 'font-size', fontSize, owner);
        saveAndSetStyle(element, 'line-height', 'normal', owner);
        saveAndSetStyle(element, 'color', '#ff102a', owner);
        saveAndSetStyle(element, '-webkit-text-fill-color', '#ff102a', owner);
        saveAndSetStyle(element, 'background-color', 'rgba(255, 16, 42, 0.10)', owner);
        saveAndSetStyle(element, 'text-shadow', '0 0 0 #ff102a', owner);
        saveAndSetStyle(element, 'text-indent', '0', owner);
        saveAndSetStyle(element, 'clip', 'auto', owner);
        saveAndSetStyle(element, 'clip-path', 'none', owner);
        saveAndSetStyle(element, 'filter', 'none', owner);
        saveAndSetStyle(element, 'overflow', 'visible', owner);
    }

    function isExcluded(element) {
        if (!element || !element.closest) return true;
        return Boolean(element.closest(
            `#${ROOT_ID}, script, style, noscript, template, svg, canvas, textarea, input, select, option, [contenteditable="true"]`
        ));
    }

    function previewElementText(element) {
        const raw = (element.innerText || element.textContent || '').replace(/\s+/g, ' ').trim();
        if (!raw) return '[элемент без текстового содержимого]';
        return raw.length > 260 ? raw.slice(0, 257) + '…' : raw;
    }

    function describeElement(element) {
        const tag = element.tagName ? element.tagName.toLowerCase() : 'element';
        const parts = [`<${tag}>`];
        if (element.id) parts.push(`#${element.id}`);
        if (typeof element.className === 'string' && element.className.trim()) {
            const classes = element.className.trim().split(/\s+/).slice(0, 3).map(name => `.${name}`).join('');
            if (classes) parts.push(classes);
        }
        const marker = element.getAttribute && element.getAttribute('data-assignment-marker');
        if (marker !== null && marker !== undefined) parts.push(`data-assignment-marker="${marker}"`);
        return parts.join(' ');
    }

    function closeResultsList() {
        activeResultsType = null;
        resultsCard.classList.remove('open');
    }

    function focusDetectedElement(element) {
        closeResultsList();
        if (!element || !element.isConnected) {
            scanPage();
            return;
        }
        try {
            element.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
            element.classList.add('anti-aristarh-result-focus');
            window.setTimeout(() => element.classList.remove('anti-aristarh-result-focus'), 1700);
        } catch (_) {}
    }

    function renderResultsList() {
        if (!activeResultsType) return;
        const isMarkers = activeResultsType === 'markers';
        const elements = [...(isMarkers ? assignmentMarkerElements : hiddenTextElements)]
            .filter(element => element && element.isConnected);

        resultsTitle.textContent = isMarkers ? 'Элементы data-assignment-marker' : 'Все скрытые HTML-элементы';
        resultsSummary.textContent = `${elements.length} ${elements.length === 1 ? 'элемент' : elements.length >= 2 && elements.length <= 4 ? 'элемента' : 'элементов'}`;
        resultsList.replaceChildren();

        if (elements.length === 0) {
            const empty = document.createElement('div');
            empty.className = 'results-empty';
            empty.textContent = 'Подходящие элементы не найдены.';
            resultsList.appendChild(empty);
            return;
        }

        const fragment = document.createDocumentFragment();
        elements.forEach((element, index) => {
            const item = document.createElement('button');
            item.type = 'button';
            item.className = 'result-item';
            item.title = 'Прокрутить страницу к этому элементу';

            const meta = document.createElement('span');
            meta.className = 'result-meta';
            meta.textContent = `${index + 1}. ${describeElement(element)}`;

            const content = document.createElement('span');
            content.className = 'result-text';
            content.textContent = previewElementText(element);

            item.append(meta, content);
            item.addEventListener('click', () => focusDetectedElement(element));
            fragment.appendChild(item);
        });
        resultsList.appendChild(fragment);
    }

    function openResultsList(type) {
        if (activeResultsType === type && resultsCard.classList.contains('open')) {
            closeResultsList();
            return;
        }
        activeResultsType = type;
        renderResultsList();
        resultsCard.classList.add('open');
    }

    totalCountTrigger.addEventListener('click', () => openResultsList('all'));
    markerCountTrigger.addEventListener('click', () => openResultsList('markers'));
    resultsClose.addEventListener('click', closeResultsList);
    shadow.addEventListener('keydown', event => {
        if (event.key === 'Escape' && resultsCard.classList.contains('open')) closeResultsList();
    });

    // Подсветка выбранного HTML-элемента на странице.
    const focusStyle = document.createElement('style');
    focusStyle.textContent = `.anti-aristarh-result-focus { outline: 2px solid #ff263d !important; outline-offset: 3px !important; }`;
    (document.head || document.documentElement).appendChild(focusStyle);

    function updatePanel() {
        markerButton.setAttribute('aria-pressed', String(state.markerReveal));
        revealButton.setAttribute('aria-pressed', String(state.reveal));
        copyButton.setAttribute('aria-pressed', String(state.blockCopy));

        markerLabel.textContent = state.markerReveal ? 'Скрыть текст' : 'Показать текст';
        revealLabel.textContent = state.reveal ? 'Скрыть ВЕСЬ текст' : 'Показать ВЕСЬ текст';
        copyLabel.textContent = state.blockCopy ? 'Разрешить копирование' : 'Заблокировать копирование';
        totalCountLabel.textContent = String(hiddenTextElements.size);
        markerCountLabel.textContent = String(assignmentMarkerElements.size);

        const activeModes = [];
        if (state.markerReveal) activeModes.push('метки показаны');
        if (state.reveal) activeModes.push('весь текст показан');
        if (state.blockCopy) activeModes.push('копирование скрытых фрагментов заблокировано');
        statusLabel.textContent = activeModes.length ? activeModes.join(' · ') : 'Режимы выключены';
        if (activeResultsType) renderResultsList();
    }

    function scanPage() {
        if (!document.body) return;

        // Пересобираем список скрытых текстовых узлов при каждом сканировании.
        hiddenTextElements.clear();
        hiddenTextNodes.clear();
        assignmentMarkerTextNodes.clear();
        assignmentMarkerElements.clear();

        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        let textNode;

        while ((textNode = walker.nextNode())) {
            if (!textNode.nodeValue || !textNode.nodeValue.trim()) continue;

            const element = textNode.parentElement;
            if (!element || isExcluded(element)) continue;

            const alreadyRevealed = findRevealedAncestor(element);
            const causes = findHiddenCauses(element);
            if (!alreadyRevealed && causes.length === 0) continue;

            hiddenTextElements.add(element);
            hiddenTextNodes.add(textNode);

            if (state.reveal) {
                for (const cause of causes) revealRoot(cause);
                highlightText(element);
            }
        }

        // Элементы data-assignment-marker считаются скрытыми специальными
        // фрагментами даже тогда, когда CSS не позволяет автоматически определить сокрытие.
        const markers = document.querySelectorAll('[data-assignment-marker]');
        for (const marker of markers) {
            if (isExcluded(marker)) continue;

            let hasText = false;
            const markerWalker = document.createTreeWalker(marker, NodeFilter.SHOW_TEXT);
            let markerTextNode;
            while ((markerTextNode = markerWalker.nextNode())) {
                if (!markerTextNode.nodeValue || !markerTextNode.nodeValue.trim()) continue;
                const textElement = markerTextNode.parentElement;
                if (!textElement || isExcluded(textElement)) continue;
                hiddenTextNodes.add(markerTextNode);
                assignmentMarkerTextNodes.add(markerTextNode);
                hiddenTextElements.add(textElement);
                hasText = true;
            }

            if (!hasText) continue;
            assignmentMarkerElements.add(marker);
            hiddenTextElements.add(marker);
            if (state.reveal) revealAssignmentMarker(marker, 'reveal');
            if (state.markerReveal) revealAssignmentMarker(marker, 'marker');
        }

        updatePanel();
    }

    function restoreRevealMode() {
        restoreStyleOwner('reveal');
        restoreHiddenAttributes();
        revealedRoots.clear();
        revealedRootReasons.clear();
        hiddenTextElements.clear();
        hiddenTextNodes.clear();
        assignmentMarkerTextNodes.clear();
        assignmentMarkerElements.clear();
    }

    function getSelectedTextNodes(range) {
        const result = [];
        const root = range.commonAncestorContainer;

        if (root.nodeType === Node.TEXT_NODE) {
            try {
                if (range.intersectsNode(root)) result.push(root);
            } catch (_) {}
            return result;
        }

        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let node;
        while ((node = walker.nextNode())) {
            try {
                if (range.intersectsNode(node)) result.push(node);
            } catch (_) {
                // Узел мог быть удалён сайтом во время выделения.
            }
        }
        return result;
    }

    function selectedTextPart(node, range) {
        let start = 0;
        let end = node.nodeValue.length;
        if (range.startContainer === node) start = range.startOffset;
        if (range.endContainer === node) end = range.endOffset;
        return node.nodeValue.slice(start, end);
    }

    function escapeHtml(value) {
        return value.replace(/[&<>\"]/g, character => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;'
        })[character]);
    }

    function createSafeClipboardContent(selection) {
        const wrapper = document.createElement('div');
        const plainParts = [];
        let containsHiddenText = false;
        let mappingFailed = false;

        for (let rangeIndex = 0; rangeIndex < selection.rangeCount; rangeIndex++) {
            const range = selection.getRangeAt(rangeIndex);
            const sourceTextNodes = getSelectedTextNodes(range);
            const fragment = range.cloneContents();
            const cloneWalker = document.createTreeWalker(fragment, NodeFilter.SHOW_TEXT);
            const clonedTextNodes = [];
            let clonedNode;
            while ((clonedNode = cloneWalker.nextNode())) clonedTextNodes.push(clonedNode);

            const rangeHasHiddenText = sourceTextNodes.some(node => hiddenTextNodes.has(node));
            containsHiddenText ||= rangeHasHiddenText;

            for (const sourceNode of sourceTextNodes) {
                if (!hiddenTextNodes.has(sourceNode)) {
                    plainParts.push(selectedTextPart(sourceNode, range));
                }
            }

            // cloneContents сохраняет порядок текстовых узлов выделения.
            // Если структура не совпала, ниже используем безопасный текстовый fallback.
            if (clonedTextNodes.length !== sourceTextNodes.length) {
                if (rangeHasHiddenText) mappingFailed = true;
            } else {
                for (let i = 0; i < clonedTextNodes.length; i++) {
                    if (hiddenTextNodes.has(sourceTextNodes[i])) clonedTextNodes[i].nodeValue = '';
                }
            }

            wrapper.appendChild(fragment);
        }

        const safeText = plainParts.join('');
        return {
            containsHiddenText,
            text: safeText,
            html: mappingFailed ? escapeHtml(safeText) : wrapper.innerHTML
        };
    }

    function blockCopyEvent(event) {
        if (!state.blockCopy) return;
        const selection = window.getSelection();
        if (!selection || selection.isCollapsed || selection.rangeCount === 0) return;

        const safeContent = createSafeClipboardContent(selection);
        if (!safeContent.containsHiddenText) return;

        // Не отменяем копирование целиком: удаляем из буфера только скрытые фрагменты.
        // Выделенный видимый текст вокруг них остаётся доступен для копирования.
        const clipboard = event.clipboardData;
        if (clipboard) {
            event.preventDefault();
            clipboard.setData('text/plain', safeContent.text);
            clipboard.setData('text/html', safeContent.html);
            event.stopImmediatePropagation();
        } else {
            // Резервный безопасный вариант для браузеров без доступного clipboardData.
            event.preventDefault();
            event.stopImmediatePropagation();
        }
    }

    markerButton.addEventListener('click', () => {
        state.markerReveal = !state.markerReveal;
        saveSettings();
        if (!state.markerReveal) restoreStyleOwner('marker');
        scanPage();
        updatePanel();
    });

    revealButton.addEventListener('click', () => {
        state.reveal = !state.reveal;
        saveSettings();
        if (!state.reveal) restoreRevealMode();
        scanPage();
        updatePanel();
    });

    copyButton.addEventListener('click', () => {
        state.blockCopy = !state.blockCopy;
        saveSettings();
        scanPage();
        updatePanel();
    });

    // Перехватываем копирование и вырезание: скрытые фрагменты вырезаются
    // из буфера, но окружающий обычный текст копируется как раньше.
    document.addEventListener('copy', blockCopyEvent, true);
    document.addEventListener('cut', blockCopyEvent, true);

    window.addEventListener('pagehide', saveSettings);

    // Следим за динамически добавляемым текстом (например, на сайтах без полной перезагрузки).
    let scanQueued = false;
    const observer = new MutationObserver(records => {
        const hasPageChanges = records.some(record => {
            const target = record.target.nodeType === 1 ? record.target : record.target.parentElement;
            if (target && target.closest && target.closest(`#${ROOT_ID}`)) return false;
            return true;
        });

        if (!hasPageChanges || scanQueued) return;
        if (!IS_ARYAPAW && mainPanel.style.display === 'none') return;
        scanQueued = true;
        queueMicrotask(() => {
            scanQueued = false;
            scanPage();
        });
    });

    observer.observe(document.body, {
        subtree: true,
        childList: true,
        characterData: true
    });

    if (IS_ARYAPAW) scanPage();
    updatePanel();
})();
